// Generates soft, illustrated placeholder "photos" (SVG) for the gallery.
// These are original artwork generated by this script (no third-party assets).
// Run: node scripts/gen-placeholders.mjs
import { mkdirSync, writeFileSync } from 'node:fs'

const out = new URL('../src/content/placeholders/', import.meta.url)
mkdirSync(out, { recursive: true })

let seed = 7
const rnd = () => ((seed = (seed * 16807) % 2147483647) / 2147483647)
const pick = (a) => a[Math.floor(rnd() * a.length)]

const palettes = [
  { sky: ['#F6D9C4', '#F3EBDD'], far: '#C9B8C9', mid: '#A9B79A', near: '#8EA383', sun: '#FBEFD9' },
  { sky: ['#CFE1EA', '#EEF2EC'], far: '#AFC4CF', mid: '#9DB4A0', near: '#7F9A85', sun: '#FFFFFF' },
  { sky: ['#E8D6E4', '#F6EEE8'], far: '#C7B4CC', mid: '#B4A4BD', near: '#8E8AA6', sun: '#FFF4EC' },
  { sky: ['#F2E2C6', '#F8F2E6'], far: '#DCC6A2', mid: '#C9AE87', near: '#A98F6E', sun: '#FFF8EA' },
  { sky: ['#2F3A57', '#596683'], far: '#3D4A66', mid: '#33405B', near: '#26304A', sun: '#F4EBD0' },
  { sky: ['#D5E5DC', '#F0F3EC'], far: '#B6CDBF', mid: '#93B09E', near: '#6F917C', sun: '#FFFFFF' },
]

function hills(w, h, y, amp, color, n = 3) {
  let d = `M0 ${h} L0 ${y}`
  const seg = n * 2
  for (let i = 1; i <= seg; i++) {
    const x = (w / seg) * i
    const cy = y + (i % 2 ? -amp : amp * 0.4) * (0.6 + rnd() * 0.6)
    d += ` Q${x - w / seg / 2} ${cy} ${x} ${y + (rnd() - 0.5) * amp * 0.5}`
  }
  return `<path d="${d} L${w} ${h} Z" fill="${color}"/>`
}
function mountains(w, h, y, color, peaks = 4) {
  let d = `M0 ${h} L0 ${y}`
  for (let i = 0; i < peaks; i++) {
    const x0 = (w / peaks) * i
    const px = x0 + (w / peaks) * (0.3 + rnd() * 0.4)
    const py = y - h * (0.15 + rnd() * 0.2)
    d += ` L${px} ${py} L${x0 + w / peaks} ${y + (rnd() - 0.5) * 20}`
  }
  return `<path d="${d} L${w} ${h} Z" fill="${color}"/>`
}
function tree(x, y, s, color) {
  return `<g transform="translate(${x} ${y}) scale(${s})"><rect x="-3" y="-10" width="6" height="22" fill="#7a6352" opacity="0.8"/><path d="M0 -70 L26 -8 L-26 -8 Z" fill="${color}"/><path d="M0 -50 L30 4 L-30 4 Z" fill="${color}" opacity="0.92"/></g>`
}
function flowers(w, h, y0, count) {
  let s = ''
  for (let i = 0; i < count; i++) {
    const x = rnd() * w
    const y = y0 + rnd() * (h - y0)
    const r = 2 + rnd() * 3 * (y / h)
    s += `<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${r.toFixed(1)}" fill="#FBF8F1" opacity="0.9"/>`
  }
  return s
}
function stars(w, h, count) {
  let s = ''
  for (let i = 0; i < count; i++)
    s += `<circle cx="${(rnd() * w).toFixed(1)}" cy="${(rnd() * h * 0.6).toFixed(1)}" r="${(0.6 + rnd() * 1.4).toFixed(1)}" fill="#fff" opacity="${(0.4 + rnd() * 0.6).toFixed(2)}"/>`
  return s
}
function balloon(x, y, s, color) {
  return `<g transform="translate(${x} ${y}) scale(${s})"><ellipse cx="0" cy="0" rx="22" ry="26" fill="${color}"/><path d="M-10 22 L-5 38 L5 38 L10 22" fill="none" stroke="#8a7a6a" stroke-width="1.5"/><rect x="-6" y="38" width="12" height="9" rx="2" fill="#a0846a"/></g>`
}

const scenes = ['hills', 'sea', 'mountains', 'night', 'forest', 'dunes', 'balloons', 'meadow']
const aspects = [1.5, 0.75, 1, 1.333, 0.8, 1.778, 1.5, 0.667, 1.25, 1, 1.5, 0.75, 1.333, 1.5, 0.8, 1.5]

const meta = []
aspects.forEach((aspect, i) => {
  const H = 800
  const W = Math.round(H * aspect)
  const scene = scenes[i % scenes.length]
  const p = scene === 'night' ? palettes[4] : pick(palettes.filter((x) => x !== palettes[4]))
  let body = ''
  const sunX = W * (0.2 + rnd() * 0.6)
  const sunY = H * (0.22 + rnd() * 0.15)
  body += `<circle cx="${sunX}" cy="${sunY}" r="${H * 0.08}" fill="${p.sun}" opacity="0.95"/>`
  if (scene === 'night') body += stars(W, H, 90)
  if (scene === 'sea') {
    body += mountains(W, H, H * 0.55, p.far, 3)
    body += `<rect x="0" y="${H * 0.58}" width="${W}" height="${H * 0.42}" fill="#9FBFCB"/>`
    for (let k = 0; k < 9; k++) body += `<rect x="${rnd() * W}" y="${H * (0.62 + rnd() * 0.3)}" width="${30 + rnd() * 80}" height="2" fill="#E9F1F2" opacity="0.7"/>`
    body += `<path d="M0 ${H} L0 ${H * 0.86} Q${W * 0.4} ${H * 0.8} ${W} ${H * 0.9} L${W} ${H} Z" fill="#E7DCC6"/>`
  } else if (scene === 'mountains') {
    body += mountains(W, H, H * 0.55, p.far, 3) + mountains(W, H, H * 0.68, p.mid, 4) + hills(W, H, H * 0.82, 30, p.near)
  } else if (scene === 'forest') {
    body += hills(W, H, H * 0.6, 40, p.far)
    for (let k = 0; k < 14; k++) body += tree(rnd() * W, H * (0.7 + rnd() * 0.2), 0.9 + rnd() * 1.4, k % 2 ? p.mid : p.near)
  } else if (scene === 'dunes') {
    body += hills(W, H, H * 0.6, 60, p.far, 2) + hills(W, H, H * 0.75, 50, p.mid, 2) + hills(W, H, H * 0.9, 30, p.near, 2)
  } else if (scene === 'balloons') {
    body += hills(W, H, H * 0.75, 30, p.mid) + hills(W, H, H * 0.88, 20, p.near)
    const cols = ['#E7B9A8', '#C9D6B8', '#F1D7A6', '#BFCFE0']
    for (let k = 0; k < 4; k++) body += balloon(W * (0.15 + 0.22 * k + rnd() * 0.05), H * (0.25 + rnd() * 0.3), 1 + rnd() * 1.2, cols[k])
  } else if (scene === 'meadow') {
    body += hills(W, H, H * 0.62, 40, p.mid) + hills(W, H, H * 0.75, 30, p.near) + flowers(W, H, H * 0.75, 120)
  } else if (scene === 'night') {
    body += mountains(W, H, H * 0.7, p.far, 4) + hills(W, H, H * 0.85, 25, p.near)
  } else {
    body += hills(W, H, H * 0.6, 50, p.far) + hills(W, H, H * 0.72, 40, p.mid) + hills(W, H, H * 0.85, 30, p.near)
  }
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">
<defs><linearGradient id="g" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${p.sky[0]}"/><stop offset="1" stop-color="${p.sky[1]}"/></linearGradient>
<radialGradient id="v" cx="0.5" cy="0.5" r="0.75"><stop offset="0.6" stop-color="#000" stop-opacity="0"/><stop offset="1" stop-color="#000" stop-opacity="0.18"/></radialGradient></defs>
<rect width="${W}" height="${H}" fill="url(#g)"/>${body}<rect width="${W}" height="${H}" fill="url(#v)"/></svg>`
  const name = `memory-${String(i + 1).padStart(2, '0')}.svg`
  writeFileSync(new URL(name, out), svg)
  meta.push({ name, aspect: +(W / H).toFixed(4), scene })
})
console.log(JSON.stringify(meta))
